<script>
  // Pricing data: [monthly, annual]
  const prices = {
    business: [18, 15],
    ai: [24, 20]
  };
  let isAnnual = false;

  function toggleBilling() {
    isAnnual = !isAnnual;
    const track = document.getElementById('billing-track');
    const labelMonthly = document.getElementById('label-monthly');
    const labelAnnual = document.getElementById('label-annual');

    if (isAnnual) {
      track.classList.add('annual');
      labelMonthly.classList.remove('active');
      labelAnnual.classList.add('active');
    } else {
      track.classList.remove('annual');
      labelMonthly.classList.add('active');
      labelAnnual.classList.remove('active');
    }
    updatePrices();
  }

  function updatePrices() {
    const bizPrice = isAnnual ? prices.business[1] : prices.business[0];
    const aiPrice = isAnnual ? prices.ai[1] : prices.ai[0];

    document.getElementById('biz-price').textContent = bizPrice;
    document.getElementById('ai-price').textContent = aiPrice;

    document.getElementById('orig-business').textContent = isAnnual ? `$${prices.business[0]}/mo billed monthly` : '\u00a0';
    document.getElementById('orig-ai').textContent = isAnnual ? `$${prices.ai[0]}/mo billed monthly` : '\u00a0';
  }

  // Team size slider
  const teamLabels = ['1–10 members', '11–25 members', '26–50 members', '51+ members'];
  function updateTeamSize(val) {
    document.getElementById('team-size-label').textContent = teamLabels[val - 1];
  }

  // FAQ accordion
  function toggleFaq(item) {
    const wasOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
    if (!wasOpen) item.classList.add('open');
  }

  // Comparison table expand
  let extraOpen = false;
  function toggleExtraRows() {
    extraOpen = !extraOpen;
    const extra = document.getElementById('extra-rows');
    const btn = document.getElementById('show-more-btn');
    const icon = document.getElementById('show-more-icon');
    const text = document.getElementById('show-more-text');

    if (extraOpen) {
      extra.classList.add('open');
      icon.style.transform = 'rotate(180deg)';
      text.textContent = 'See fewer features';
    } else {
      extra.classList.remove('open');
      icon.style.transform = '';
      text.textContent = 'See all features';
    }
  }
</script>
